"""Kullanım etiketleri: sayılamaz isimler ve Amerikan/İngiliz İngilizcesi çiftleri -> lab.js"""
import json,os,subprocess
ROOT=os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
have=set(json.loads(subprocess.check_output(['node','-e',"global.window={};require('%s/words.js');process.stdout.write(JSON.stringify(window.WORDS.map(w=>w[0])))"%ROOT])))
U="advice information news furniture luggage baggage equipment homework research knowledge traffic weather money bread rice music travel accommodation progress evidence damage rubbish pollution behaviour health fun luck permission scenery software patience courage electricity transport clothing jewellery machinery feedback vocabulary grammar leisure violence wealth poverty safety sugar cash education employment garbage applause anger happiness housework sunshine stuff advertising harm litter nonsense". split()
AB=[("truck","lorry","kamyon"),("elevator","lift","asansör"),("apartment","flat","daire"),("gasoline","petrol","benzin"),("candy","sweets","şeker, şekerleme"),("cookie","biscuit","bisküvi, kurabiye"),("sidewalk","pavement","kaldırım"),("subway","underground","metro"),("vacation","holiday","tatil"),("fall","autumn","sonbahar"),("movie","film","film"),("mail","post","posta"),("trash","rubbish","çöp"),("garbage","rubbish","çöp"),("eraser","rubber","silgi"),("pants","trousers","pantolon"),("sneakers","trainers","spor ayakkabı"),("faucet","tap","musluk"),("closet","wardrobe","gardırop, dolap"),("drugstore","chemist","eczane"),("restroom","toilet","tuvalet"),("railroad","railway","demiryolu"),("zipper","zip","fermuar"),("cell phone","mobile phone","cep telefonu"),("french fries","chips","patates kızartması"),("parking lot","car park","otopark"),("freeway","motorway","otoyol"),("schedule","timetable","tarife, program"),("attorney","lawyer","avukat"),("soccer","football","futbol"),("airplane","aeroplane","uçak"),("mall","shopping centre","alışveriş merkezi"),("round trip","return","gidiş-dönüş"),("check","bill","hesap (restoranda)"),("line","queue","kuyruk, sıra"),("flashlight","torch","el feneri"),("highway","motorway","otoyol"),("store","shop","dükkân, mağaza"),("cab","taxi","taksi")]
u=[x for x in U if x in have]
ab=[[a,b,t] for a,b,t in AB if a in have or b in have]
open(os.path.join(ROOT,'lab.js'),'w',encoding='utf8').write('/* Kullanım etiketleri. tools/conf/lab.py ile üretilir. u: sayılamaz isimler; ab: [Amerikan, İngiliz] çiftleri. */\nwindow.LAB='+json.dumps({'u':u,'ab':ab},ensure_ascii=False,separators=(',',':'))+';\n')
print('sayılamaz',len(u),'/',len(U),'çift',len(ab),'/',len(AB),[a for a,b,t in AB if a not in have and b not in have])
